  add('pinzas-6','Cuenta y pon la pinza · 1-6','Matemáticas','pinzas','Contar y elegir una cantidad entre tres opciones.','Cuenta los puntos y coloca una pinza en el número correspondiente.',{max:6});
  add('huevos-6','Un nido para cada cantidad','Matemáticas','huevos','Construir colecciones de 1 a 6 elementos.','Pon un huevo de papel en cada espacio y empareja la tarjeta de número.',{project:'Dinosaurios',max:6});
  add('marcos-10','Llenamos marcos · del 1 al 10','Matemáticas','marcos','Representar cantidades organizadas en dos filas.','Comienza con una fila de cinco. Usa la segunda solo cuando resulte cómoda.',{max:10,ages:[4,5]});
  add('recta','La recta que se pisa','Matemáticas','recta','Vincular pasos, orden y números.','Recorta y une la recta del 1 al 10. Usa primero solo el tramo 1-6.',{duration:15});
  add('subitizacion','Lo veo sin contar · 1-4','Matemáticas','subitizacion','Reconocer pequeñas cantidades y comprobarlas.','Muestra una tarjeta brevemente, vuelve a enseñarla y permite contar para comprobar.',{max:4,duration:8});
  add('juntar','Llegan más al grupo','Matemáticas','juntar','Resolver situaciones de juntar sin algoritmo.','Representa cada relato con piezas. Junta los dos grupos y cuenta el total.',{max:6,project:'Dinosaurios',ages:[4,5]});
  add('completar','¿Cuántos faltan en la colección?','Matemáticas','completar','Completar una colección hasta una cantidad pequeña.','Coloca las piezas que faltan en los espacios vacíos y comprueba el total.',{max:6});
  add('orden-cantidad','De pocos a muchos','Matemáticas','orden','Comparar colecciones por correspondencia.','Empareja las piezas una a una y ordena las tarjetas de menor a mayor cantidad.',{max:6});
  add('dado-puntos','Mi primer dado · 1, 2 y 3','Juegos','dado','Asociar puntos con desplazamientos cortos.','Monta el dado con ayuda adulta. Avanza una casilla por cada punto.',{max:3});
  add('series-ab','Series AB · formas','Matemáticas','series','Reconocer la unidad que se repite.','Nombra círculo-cuadrado, repite y completa con las piezas recortables.',{pattern:'AB',theme:'formas'});
  add('series-aab','Series AAB · dinosaurios','Matemáticas','series','Continuar una unidad de tres elementos.','Señala el grupo que se repite: dos iguales y uno distinto. Copia antes de continuar.',{pattern:'AAB',theme:'dinos',project:'Dinosaurios'});
  add('series-abb','Series ABB · formas y colores','Matemáticas','series','Distinguir una repetición ABB.','Agrupa una pieza A y dos B. Continúa la tira con las piezas de abajo.',{pattern:'ABB',theme:'formas',ages:[4,5]});
  add('series-abc','Series ABC · tres dinosaurios','Matemáticas','series','Mantener el orden de tres elementos diferentes.','Copia la unidad completa antes de intentar continuar sin modelo.',{pattern:'ABC',theme:'dinos',project:'Dinosaurios',ages:[4,5]});
  add('series-aabb','Series AABB · por parejas','Matemáticas','series','Identificar parejas que se repiten.','Rodea cada bloque AABB con el dedo y coloca las tarjetas que faltan.',{pattern:'AABB',theme:'formas',ages:[4,5]});
  add('crea-series','El taller de inventar series','Lógica','crea-series','Crear y explicar un patrón propio.','Elige dos o tres tipos de piezas. Construye, repite y deja un hueco para tu pareja.');
  add('clasificar','Cada forma en su grupo','Lógica','clasificar','Clasificar por un atributo y cambiar de criterio.','Agrupa primero por forma; mezcla y vuelve a agrupar por color. En blanco y negro, usa la trama.');
  add('dos-atributos','La mesa de las dos pistas','Lógica','atributos','Combinar forma y tamaño.','Elige una forma y un tamaño. Coloca cada pieza en la casilla que cumple las dos pistas.',{ages:[4,5]});
  add('tamanos','Dinosaurios grandes y pequeños','Matemáticas','tamanos','Comparar el tamaño de representaciones.','Ordena cada familia de dibujos. Hablamos del tamaño del dibujo, no de escalas reales.',{project:'Dinosaurios'});
  add('intrusos','Detectives: uno es diferente','Lógica','intrusos','Explicar semejanzas y diferencias.','Mira cada grupo y señala el diferente. Escucha otras clasificaciones razonables.');
  add('que-falta','Observa, tapa y recuerda','Lógica','memoria-modelo','Recordar una pequeña colección.','Mira el modelo, tapa una pieza y busca cuál falta entre los recortables.');
  add('sombras','Siluetas y dinosaurios','Lógica','sombras','Emparejar contornos por sus rasgos.','Observa las ilustraciones y busca su silueta sin fijarte en el color.',{project:'Dinosaurios'});
  add('secuencias','Primero, después y al final','Lenguaje','secuencias','Ordenar hechos y narrarlos con ayuda.','Ordena tres tarjetas de una rutina. La maestra lee las frases; el niño cuenta o representa.');
  add('puzles','Puzles de dinosaurios · 2 y 4 piezas','Lógica','puzles','Reconstruir una imagen usando sus partes.','Ofrece primero el puzle de dos mitades; conserva el modelo como apoyo.',{project:'Dinosaurios'});
  add('laberintos','Tres caminos al encuentro','Grafomotricidad','laberintos','Planificar un recorrido antes de trazar.','Busca la salida con el dedo. Después recorre con un muñeco o una cera ancha.');
  add('rimas','Parejas que suenan parecido','Lenguaje','rimas','Escuchar y reconocer semejanzas al final de palabras.','Nombra las imágenes en voz alta: gato-pato, queso-hueso, conejo-espejo. Empareja por sonido.');
  add('silabas','Palabras con palmadas','Lenguaje','silabas','Segmentar palabras orales en sílabas.','La maestra nombra cada dibujo. Da una palmada por sílaba y coloca una pieza por golpe.');
  add('sonidos','Empiezan como…','Lenguaje','sonidos','Comparar sonidos iniciales de palabras familiares.','Escucha sol-sopa-silla y mariposa-mano-moto. Agrupa por el sonido inicial, sin deletrear.');
  add('letras','Letras móviles mayúsculas','Lenguaje','letras','Explorar las letras a partir del propio nombre.','La maestra prepara el nombre modelo. Busca las mismas letras y ordénalas con apoyo.');
  add('nombre','Mi nombre, pieza a pieza','Lenguaje','nombre','Reconocer la identidad escrita del nombre propio.','La maestra escribe el nombre en el modelo y en las piezas. Ordena por comparación visual.');
  add('vocales','Busca la misma letra','Lenguaje','vocales','Discriminar visualmente letras con apoyo de un modelo.','Mira la letra grande y señala las iguales. No exige leer palabras.');
  add('historias','Tres tarjetas, una historia','Lenguaje','historias','Inventar relatos orales breves.','Saca un personaje, un lugar y un objeto. Inventa qué ocurre, con ayuda de la maestra.');
  add('vocab-dino','Palabras de paleontología','Lenguaje','vocabulario','Comprender vocabulario nuevo dentro del proyecto.','Presenta solo tres palabras con gesto y objetos reales; revisa después sus tarjetas.',{project:'Dinosaurios'});
  add('dinos','Conocemos nueve dinosaurios','Proyecto','dinosaurios','Observar rasgos y comparar dinosaurios.','Presenta un dinosaurio por día. Busca su rasgo distintivo y clasifica por alimentación.',{project:'Dinosaurios'});
  add('trazos-rectos','Caminos de lado a lado','Grafomotricidad','trazos','Coordinar movimientos amplios horizontales y verticales.','Recorre primero con el dedo, luego con una cera gruesa. Elige solo uno o dos caminos.',{trace:'rectos'});
  add('trazos-curvos','Curvas, ondas y espirales','Grafomotricidad','trazos','Explorar trazos curvos en un recorrido lúdico.','Sigue con el dedo una curva. Crea otra con un cordón antes de llevarla al papel.',{trace:'curvos'});
  add('recorte','Tiras para cortar y construir','Motricidad fina','recorte','Coordinar apertura y cierre de tijeras.','Corta por las líneas anchas y usa los trozos para crear un collage libre.');
  add('plastilina','Taller de bolitas y churros','Motricidad fina','plastilina','Fortalecer destrezas manuales mediante modelado.','Rellena los círculos con bolitas y las líneas con churros de plastilina. No hace falta exactitud.');
  add('ensartar','Collares de formas gigantes','Motricidad fina','ensartar','Coordinar ambas manos al pasar una cinta.','Un adulto perfora las tarjetas. Pasa un cordón corto de punta rígida por los agujeros.',{safety:'Cordones cortos, sin lazos al cuello y con supervisión continua. Perforaciones a cargo del adulto.'});
  add('puntos','De punto en punto · 1-6','Grafomotricidad','puntos','Seguir un orden pequeño con guía visual.','Une hasta seis puntos con el dedo o una cera; la maestra acompaña el conteo.');
  add('memory-dino','Memory de dinosaurios','Juegos','memory','Recordar posiciones y encontrar parejas.','Empieza con tres parejas boca arriba; después juega con cuatro parejas boca abajo.',{project:'Dinosaurios'});
  add('domino-dino','Dominó de dinosaurios','Juegos','domino','Conectar imágenes iguales respetando turnos.','Une los extremos con el mismo dinosaurio. Juego cooperativo: entre todos formamos el camino.',{project:'Dinosaurios'});
  add('bingo-dino','Bingo de dinosaurios','Juegos','bingo','Discriminar imágenes y atender a una señal.','Reparte los seis cartones distintos. Saca una tarjeta de llamada y tapa la imagen igual.',{project:'Dinosaurios'});
  add('loto-dino','Loto de tres dinosaurios','Juegos','loto','Emparejar imágenes iguales con un modelo visible.','Entrega un tablero de tres y las tarjetas mezcladas. Coloca cada dinosaurio encima de su pareja.',{project:'Dinosaurios'});
  add('yo-tengo','Yo tengo… ¿quién tiene?','Juegos','yo-tengo','Escuchar una pista y continuar una cadena visual.','La maestra lee la primera tarjeta. Quien tiene la imagen buscada muestra la suya y seguimos.',{project:'Dinosaurios'});
  add('busca-dino','Busca y encuentra dinosaurios','Juegos','busca','Mantener la atención y comparar detalles visuales.','Busca los dinosaurios del modelo en la colección y márcalos con una pieza grande.',{project:'Dinosaurios'});
  add('tablero','Camino al museo','Juegos','tablero','Contar desplazamientos de uno en uno.','Usa el dado 1-3 y una ficha grande por pareja. Avanza hasta el museo sin retrocesos ni eliminaciones.',{project:'Dinosaurios'});
  add('ruleta','Ruleta de movimientos','Psicomotricidad','ruleta','Interpretar una señal y variar el movimiento.','Deja caer una ficha sobre un sector, lee la acción y represéntala; también se puede hacer sentado.');
  add('movimientos','Nos movemos como dinosaurios','Psicomotricidad','movimientos','Explorar equilibrio, desplazamientos y paradas.','Saca una tarjeta. Repite el movimiento en un espacio despejado, sin carreras ni empujones.',{project:'Dinosaurios'});
  add('alimentacion','¿Plantas u otros animales?','Proyecto','alimentacion','Clasificar dinosaurios por su alimentación.','Nombra la comida y coloca cada tarjeta en su panel. Comer carne no significa ser malo.',{project:'Dinosaurios'});
  add('carteles','Rincón de paleontología · carteles','Proyecto','carteles','Organizar un espacio de juego simbólico.','Coloca las señales a la altura del grupo. Explica dónde descubrir, limpiar y exponer.',{project:'Dinosaurios'});
  add('carnets','Carnets de nuestro equipo','Proyecto','carnets','Participar en un rol de investigación compartido.','Cada niño dibuja su retrato y dicta su nombre. La maestra prepara los carnets sin datos personales extra.',{project:'Dinosaurios'});
  add('descubrimiento','Mi descubrimiento para el museo','Proyecto','descubrimiento','Registrar una observación con dibujo y dictado.','Dibuja el objeto, señala tamaño y dicta una idea a la maestra.',{project:'Dinosaurios'});
  add('etiquetas','Etiquetas de herramientas y hallazgos','Proyecto','etiquetas','Nombrar y ordenar objetos del rincón.','Empareja etiquetas con herramientas reales de juego; la maestra lee y explica su uso.',{project:'Dinosaurios'});
  add('diplomas','Celebramos nuestra investigación','Proyecto','diplomas','Reconocer el esfuerzo colectivo sin comparar.','Entrega a todos un diploma con una aportación concreta que la maestra escribe o el niño dibuja.',{project:'Dinosaurios'});
  add('coronas','Coronas para el museo','Arte','coronas','Diseñar un complemento con patrones y collage.','Recorta la banda con ayuda. Decora con formas y ajusta sin grapas en contacto con la piel.',{project:'Dinosaurios'});
  add('collage','Un dinosaurio con formas','Arte','collage','Componer libremente una figura con formas.','Recorta o rasga las piezas. Decide cómo combinarlas sin exigir copiar un modelo.',{project:'Dinosaurios'});
  add('huevo-arte','Un huevo lleno de texturas','Arte','huevo-arte','Explorar estampación y collage dentro y fuera de un contorno.','Decora el huevo con papel rasgado, estampaciones o ceras; explica tu elección.',{project:'Dinosaurios'});
  add('falso-verdadero','Pistas de dinosaurios · ¿sí o no?','Proyecto','verdadero','Distinguir hechos sencillos y fantasía.','La maestra lee una afirmación y muestra dos opciones. Después descubre la explicación.',{project:'Dinosaurios'});
  add('museo-plan','¿Qué sabemos? ¿Qué investigamos?','Asamblea','museo-plan','Hacer visibles las preguntas y descubrimientos del grupo.','Recoge dibujos o dictado en tres paneles: creemos, queremos saber y hemos descubierto.',{project:'Dinosaurios'});
  add('kusama-mirar','Miramos puntos, calabazas y espacios','Proyecto','kusama-mirar','Observar, comparar y conversar a partir de tres imágenes visuales sencillas.','Presenta una lámina cada vez. Usa los marcos para localizar puntos, líneas, formas y espacios.',{project:'Yayoi Kusama',kusamaGroup:'imprimibles',duration:15,materials:['PDF A4 impreso','Marcos de observación recortados por un adulto','Círculos grandes para votar'],preparation:'Imprime las tres páginas. El adulto recorta los marcos por el borde exterior; no es necesario recortar el centro.',steps:['Muestra una imagen y deja unos segundos para observar.','Formula una sola pregunta visual y acepta respuestas señaladas.','Compara dos imágenes y busca algo que se repite.','Elige una imagen para volver a mirar.'],easy:'Usa solo dos láminas y una pregunta: ¿ves puntos o líneas?',extend:'Busca una semejanza y una diferencia entre dos láminas.',safety:'Usa las láminas con luz estable y permite apartar la mirada o descansar.'});
  add('kusama-series-puntos','Cuatro series de puntos · AB, AAB, ABB y ABC','Matemáticas','kusama-series','Reconocer y continuar patrones visuales sin depender de piezas recortables.','Elige una página. Señala la unidad que se repite y completa los huecos dibujando, estampando o colocando objetos propios.',{project:'Yayoi Kusama',kusamaGroup:'imprimibles',duration:15,materials:['PDF A4 impreso','Ceras gruesas o sellos redondos','Objetos circulares grandes opcionales'],preparation:'Imprime solo el patrón que quieras trabajar. Cada página contiene cuatro series y no incluye piezas recortables.',steps:['Señala y nombra la unidad que se repite.','Lee la serie de izquierda a derecha.','Completa cada hueco con dibujo, sello u objetos que ya tengas.','Comprueba la serie volviendo a señalarla desde el inicio.'],easy:'Empieza por la página AB y completa un solo hueco por fila.',extend:'Continúa AAB, ABB o ABC y explica qué parte se repite.',safety:'Si usas piezas móviles, deben ser grandes y estar supervisadas.'});
  add('kusama-calabazas','Calabazas para observar, modelar y crear','Arte','kusama-calabazas','Disponer de siluetas amplias y referencias sencillas para varias propuestas de calabazas.','Elige la página según la actividad: observar surcos, modelar, decorar o preparar una obra colectiva.',{project:'Yayoi Kusama',kusamaGroup:'imprimibles',duration:20,materials:['PDF A4 impreso','Ceras gruesas, pintura lavable o círculos de papel','Plastilina no tóxica opcional'],preparation:'Imprime solo las siluetas necesarias. Para el mural, amplía una página o úsala como modelo para dibujar en papel continuo.',steps:['Observa el contorno y los surcos.','Elige si vas a trazar, modelar o decorar.','Añade puntos grandes dejando zonas sin cubrir.','Compara dos resultados sin pedir que sean iguales.'],easy:'Usa una silueta grande y un solo material.',extend:'Alterna tamaños de puntos o crea dos calabazas distintas.',safety:'El adulto recorta si hace falta. Usa materiales no tóxicos y piezas grandes.'});
  add('kusama-cantidades','Calabazas y puntos · del 1 al 6','Matemáticas','kusama-cantidades','Construir y comprobar colecciones de uno a seis sobre soportes claros.','Coloca la tarjeta de cantidad junto a una calabaza y añade un punto cada vez hasta completar la colección.',{project:'Yayoi Kusama',kusamaGroup:'imprimibles',duration:15,materials:['PDF A4 impreso','Círculos grandes reutilizables o pegatinas grandes','Bandeja'],preparation:'Imprime las tarjetas de calabaza y cantidad. El adulto recorta solo las páginas que vaya a utilizar.',steps:['Elige una tarjeta de cantidad.','Coloca un punto cada vez mientras cuentas.','Comprueba tocando cada punto una sola vez.','Cambia la cantidad y decide si hay que añadir o retirar.'],easy:'Trabaja con 1, 2 y 3 y presenta una colección modelo.',extend:'Compara dos calabazas: más, menos o la misma cantidad.',safety:'Recorta el adulto y utiliza piezas grandes que no puedan tragarse.'});
  add('kusama-clasificar','Círculos para clasificar por tamaño y color','Lógica','kusama-clasificar','Cambiar de criterio al ordenar círculos grandes, medianos y pequeños.','Recorta los círculos grandes y utiliza primero las bases de tamaño; después mezcla y clasifica por color o por marcas.',{project:'Yayoi Kusama',kusamaGroup:'imprimibles',duration:15,materials:['PDF A4 impreso','Tres bandejas o aros opcionales','Tijeras de adulto'],preparation:'El adulto recorta los círculos por el borde discontinuo. Presenta pocas piezas y un único criterio al comenzar.',steps:['Compara dos círculos superponiéndolos.','Agrupa por tamaño.','Mezcla y agrupa por color o por marcas.','Explica por qué una pieza cambia de grupo cuando cambia la regla.'],easy:'Usa solo grande y pequeño con cuatro piezas.',extend:'Busca una pieza que cumpla dos pistas a la vez.',safety:'Piezas grandes, bordes redondeados y supervisión durante el uso.'});
  add('kusama-flores','Flores grandes de puntos','Arte','kusama-flores','Combinar pétalos y centros circulares para crear flores variadas.','Usa los pétalos como plantilla, como piezas para componer o como inspiración para dibujar una flor propia.',{project:'Yayoi Kusama',kusamaGroup:'imprimibles',duration:25,materials:['PDF A4 impreso','Pegamento infantil','Ceras gruesas','Tijeras de adulto'],preparation:'El adulto recorta pétalos y centros si se usarán como piezas. También pueden rasgarse o copiarse sobre papel de color.',steps:['Elige un centro circular.','Prueba varias posiciones de los pétalos antes de pegar.','Añade puntos dentro, fuera o alrededor.','Reúne varias flores para formar un jardín común.'],easy:'Ofrece un centro y cuatro pétalos grandes.',extend:'Crea una regla de color o compara dos composiciones.',safety:'Las piezas las prepara un adulto o se rasgan a mano. Usa pegamento infantil.'});
  add('kusama-redes-imprimible','Redes y bucles para continuar','Grafomotricidad','kusama-redes','Continuar gestos amplios de bucles y observar sus huecos sin exigir precisión.','Empieza en los trazos ya iniciados y continúa solo durante un tiempo breve, con el color y el tamaño que resulten cómodos.',{project:'Yayoi Kusama',kusamaGroup:'imprimibles',duration:12,materials:['PDF A4 impreso','Ceras gruesas','Marco de cartulina opcional'],preparation:'Imprime una página y colócala en horizontal sobre una mesa amplia.',steps:['Recorre con el dedo un bucle ya dibujado.','Continúa al lado, arriba o abajo.','Cambia de color cuando quieras.','Mira una zona con el marco y descubre caminos y huecos.'],easy:'Completa una sola fila de bucles grandes.',extend:'Conecta dos redes o alterna dos colores.',safety:'No prolongues la repetición si produce cansancio o incomodidad visual.'});
  add('kusama-espacios','Puntos y señales para transformar el espacio','Proyecto','kusama-espacios','Preparar círculos y señales grandes para una instalación o un recorrido seguro.','Elige únicamente las páginas que necesites: puntos de color, puntos de bajo consumo, señales o registro del antes y después.',{project:'Yayoi Kusama',kusamaGroup:'imprimibles',duration:20,materials:['PDF A4 impreso','Cinta reposicionable de baja adherencia colocada por un adulto','Paneles de cartón o suelo antideslizante'],preparation:'El adulto recorta y prueba el adhesivo. Para caminar, pega cada círculo por completo sobre una base antideslizante.',steps:['Decide qué superficie móvil se va a transformar.','Coloca pocos puntos y observa el cambio.','Añade señales solo si hay un recorrido.','Retira y guarda el material al terminar.'],easy:'Transforma una sola caja o un panel.',extend:'Ordena fotografías o dibujos del antes y el después.',safety:'Nunca pegues en zonas de paso sin fijación, enchufes, cristales, piel o ropa.'});
  add('kusama-cuento','El punto viajero · personajes y escenarios','Lenguaje','kusama-cuento','Apoyar un relato oral con un personaje circular, escenarios y una secuencia de tres momentos.','Elige un punto y un escenario. Cada participante añade una acción breve, una palabra, un gesto o un sonido.',{project:'Yayoi Kusama',kusamaGroup:'imprimibles',duration:18,materials:['PDF A4 impreso','Caja o sobre','Ceras gruesas opcionales'],preparation:'Imprime los escenarios y la secuencia. El adulto recorta los personajes circulares si se van a mover.',steps:['Descubre el punto protagonista.','Elige aula, jardín o cielo.','Añade un encuentro o una acción.','Ordena inicio, viaje y llegada y vuelve a contar.'],easy:'Ofrece dos escenarios y preguntas de elección.',extend:'Añade un problema sencillo y dos finales posibles.',safety:'Respeta el derecho a escuchar o pasar turno; no es necesario escribir.'});
  add('kusama-museo-imprimible','Nuestro museo · carteles, etiquetas e invitación','Proyecto','kusama-museo','Organizar y comunicar una exposición de aula con apoyos claros y personalizables.','Escoge los carteles que necesites. Los títulos y mensajes se completan con dibujo o dictado al adulto.',{project:'Yayoi Kusama',kusamaGroup:'imprimibles',duration:25,materials:['PDF A4 impreso','Rotulador grueso para el adulto','Cinta de baja adherencia','Creaciones del grupo'],preparation:'Imprime solo las páginas necesarias y completa los textos con el grupo antes de montar la exposición.',steps:['Clasifica las creaciones por puntos, formas y espacios.','Dicta un título breve.','Prepara una invitación o una etiqueta.','Ensaya el recorrido y una frase para recibir a los visitantes.'],easy:'Usa tres carteles y una etiqueta por obra.',extend:'Prepara una pregunta para visitantes o una visita guiada breve.',safety:'Fija los trabajos, deja libres puertas y pasillos y no publiques datos personales.'});
