  add('carnaval-cuatro-actividades','Carnaval · cuatro actividades','Proyecto','pdf-aportado','Practicar lectoescritura, series, conteo y atención visual con un tema de Carnaval.','Escoge una actividad: letras perdidas, series de antifaces, conteo o quién se esconde.',{externalPdf:'carnaval-cuatro-actividades.pdf',moment:'Carnaval',duration:18,sourceNote:'Infanity y Tesoros Brillantes · Material aportado por la maestra',materials:['PDF A4 impreso','Ceras gruesas','Tijeras de adulto si se separan tarjetas'],preparation:'Imprime solo las páginas necesarias. Presenta una actividad por sesión y conserva las soluciones para la maestra.',steps:['Mira el modelo y escucha la consigna.','Resuelve señalando, uniendo o completando.','Comprueba con una segunda mirada.','Cuenta cómo has encontrado la respuesta.'],easy:'Reduce el número de opciones o tapa parte de la página.',extend:'Inventa otra palabra, serie o tarjeta de conteo de Carnaval.',safety:'Los recortes los prepara un adulto. Conserva los créditos del material original.'});
  add('kusama-colorea-retrato','Yayoi Kusama · retrato para colorear','Arte','aportado-imagen','Observar rasgos, puntos y vestuario mientras se colorea una lámina aportada.','Colorea libremente el retrato y conversa sobre los puntos que se repiten.',{project:'Yayoi Kusama',kusamaGroup:'imprimibles',sourceImage:'assets/kusama/yayoi-colorear-aportada.png',sourceNote:'Lámina aportada por la maestra · Revisar condiciones de uso antes de compartir',materials:['Lámina A4 impresa','Ceras o lápices de colores'],preparation:'Imprime una copia por niño. Mantén la imagen completa y no elimines marcas de autoría si las hubiera.',steps:['Observa el peinado, la ropa y los puntos.','Elige libremente los colores.','Busca círculos grandes y pequeños.','Cuenta algo que hayas descubierto.'],easy:'Colorea solo los puntos grandes.',extend:'Crea un patrón de dos colores en el fondo.',safety:'Uso educativo en el aula. Comprueba los derechos de la imagen antes de redistribuirla.'});
  add('kusama-colorea-personaje','Personaje entre puntos · lámina para colorear','Arte','aportado-imagen','Explorar círculos de distintos tamaños y colorear una composición aportada.','Colorea el personaje y crea una regla de color para los círculos del fondo.',{project:'Yayoi Kusama',kusamaGroup:'imprimibles',sourceImage:'assets/kusama/puntos-personaje-aportado.png',sourceNote:'Lámina aportada por la maestra · Conserva la autoría visible',materials:['Lámina A4 impresa','Ceras o lápices de colores'],preparation:'Imprime la lámina completa sin recortar el logotipo o las marcas visibles.',steps:['Observa los círculos del fondo.','Elige dos o tres colores.','Colorea siguiendo una regla propia o libremente.','Explica qué círculos llaman más tu atención.'],easy:'Colorea únicamente el personaje y tres círculos.',extend:'Alterna colores según el tamaño de cada círculo.',safety:'Esta lámina contiene un personaje de terceros. Úsala solo si dispones del permiso o licencia correspondiente.'});
