  activity('excavacion','Una excavación de papel','Proyecto','Buscar con cuidado y describir un hallazgo.',['Tiras de papel grandes','Bandeja','Figuras grandes de dinosaurios','Brochas suaves','Lámina Mi descubrimiento'],'Esconde tres figuras entre tiras de papel; deja las brochas junto a la bandeja.',['Observa la bandeja y anticipa qué puede esconder.','Retira el papel con las manos y la brocha sin golpear.','Dibuja un hallazgo y dicta una observación.','Traslada el hallazgo al museo y repón el rincón.'],20,{project:'Dinosaurios',type:'Experimento',related:['descubrimiento','carteles','carnets'],easy:'Deja una parte de la figura visible y busca una sola.',safety:'Sin arena suelta, polvo ni objetos frágiles. Usa figuras grandes, brochas sin puntas y material limpio.'});
  activity('fosiles','Huellas que se quedan','Proyecto','Diferenciar un molde de juego de un fósil real.',['Plastilina no tóxica','Figuras grandes','Hojas grandes','Bandejas'],'Prepara discos de plastilina del tamaño de una mano.',['Presiona una figura o una hoja sobre la plastilina.','Retira despacio y compara marca y objeto.','Adivina qué objeto dejó otra marca.','Explica: hemos hecho un molde; un fósil real necesita procesos naturales y mucho tiempo.'],20,{project:'Dinosaurios',type:'Experimento',related:['vocab-dino','descubrimiento']});
  activity('hielo','Rescatamos un huevo de hielo','Proyecto','Observar cambios al pasar de hielo a agua.',['Bloques grandes de hielo preparados por un adulto','Bandejas','Agua a temperatura ambiente','Vasos pequeños sin roturas'],'Congela agua sola en recipientes ovalados; no encierres piezas pequeñas.',['Toca el hielo brevemente con una cuchara o a través de una tela.','Pon unas gotas de agua sobre un bloque y deja otro sin gotas.','Mira qué cambia; sin competir por rapidez.','Dibuja o cuenta qué ha ocurrido con el hielo.'],20,{project:'Dinosaurios',type:'Experimento',easy:'Observa un solo bloque con ayuda del adulto.',safety:'El adulto manipula el hielo. No usar agua caliente, sal, golpes ni martillos; no meter hielo en la boca. Secar derrames.'});
  activity('volcan','Un volcán de burbujas','Proyecto','Observar una transformación y distinguir modelo y realidad.',['Bandeja amplia','Vaso pequeño abierto','Una cucharadita de bicarbonato','Un poco de vinagre de cocina'],'El adulto coloca el vaso en la bandeja, lejos de la cara de los niños.',['Anticipa qué cambiará al mezclar.','El adulto añade lentamente vinagre al bicarbonato.','Observa las burbujas desde una distancia cómoda.','Aclara: esto es un modelo de espuma; un volcán real no funciona con vinagre.'],10,{project:'Dinosaurios',type:'Experimento',easy:'Mira la demostración sin tocar los materiales.',safety:'Demostración del adulto. Recipiente abierto, cantidades pequeñas; no tapar, ingerir, acercar a ojos ni mezclar con otros productos. No es una explicación de la extinción.'});
  activity('huellas-pintura','Caminos de huellas','Arte','Comparar marcas y explorar estampación.',['Papel continuo','Témpera lavable no tóxica','Figuras grandes con base estable','Paños'],'Protege la mesa y prepara una capa fina de pintura.',['Estampa una pata o base sobre el papel.','Haz un camino de marcas separadas y otro de marcas juntas.','Compara los caminos sin deducir velocidades reales de estas figuras.','Lava las figuras con ayuda y deja secar el mural.'],20,{project:'Dinosaurios',related:['trazos-rectos']});
  activity('medimos','¿Cuántos pasos mide?','Matemáticas','Comparar longitudes usando una unidad no convencional.',['Cinta de pintor','Tarjetas de dinosaurios','Bloques iguales'],'Marca dos líneas de longitudes diferentes en el suelo sin obstaculizar el paso.',['Elige una línea y cúbrela con bloques iguales.','Repite con la otra y compara las colecciones.','Prueba con pasos y observa que no todos los pasos miden igual.','Aclara que las líneas son modelos inventados, no tamaños reales de especies.'],20,{project:'Dinosaurios',related:['tamanos','recta']});
  activity('esqueletos','Huesos de papel','Arte','Construir una representación a partir de partes.',['Tiras anchas de papel blanco','Cartulina oscura','Pegamento infantil','Tarjetas de dinosaurios'],'Prepara tiras cortas y largas; evita bastoncillos pequeños si hay riesgo de llevarlos a la boca.',['Observa el cuerpo de un dinosaurio en una tarjeta.','Elige tiras para cabeza, cuerpo, patas y cola.','Compón tu representación y pega solo cuando estés conforme.','Cuenta qué parte has representado: es una creación, no una reconstrucción anatómica exacta.'],25,{project:'Dinosaurios',related:['dinos']});
  activity('platos','Dinosaurios de cartón','Arte','Planificar una composición con materiales cotidianos.',['Plato de cartón cortado por un adulto','Papel de colores','Pegamento infantil','Ceras'],'El adulto prepara medios platos y piezas grandes sin bordes cortantes.',['Elige un medio plato como cuerpo.','Añade cuello, patas o placas de papel a tu gusto.','Decora mediante manchas o líneas amplias.','Presenta el dinosaurio como personaje inventado.'],25,{project:'Dinosaurios',related:['collage']});
  activity('modelado-dino','Un dinosaurio de plastilina','Motricidad fina','Combinar bolitas, churros y piezas aplastadas.',['Plastilina no tóxica','Base de trabajo','Tarjetas de dinosaurios'],'Distribuye porciones grandes fáciles de manejar.',['Explora cómo hacer una bola y un churro.','Combina varias piezas para inventar un cuerpo.','Añade un rasgo que hayas observado: cuello, placas o cola.','Explica con gesto o palabra qué has creado.'],20,{project:'Dinosaurios',related:['plastilina','dinos']});
  activity('circuito','La expedición tranquila','Psicomotricidad','Encadenar desplazamientos y coordinar acciones.',['Cinta de suelo','Aros apoyados','Pelotas blandas grandes','Cajas bajas'],'Prepara un camino ancho, una zona de equilibrio a ras de suelo y un nido.',['Camina por la línea o síguela sentado con los brazos.','Pasa alrededor de dos aros, sin saltos obligatorios.','Transporta un huevo de pelota con ambas manos.','Llega al nido y espera a tu pareja.'],20,{project:'Dinosaurios',related:['movimientos','ruleta'],safety:'Sin alturas, ojos tapados, carreras ni obstáculos rígidos. Ofrece recorrido accesible y supervisa continuamente.'});
  activity('volcan-movimiento','Buscamos una zona segura','Psicomotricidad','Responder a señales y regular la velocidad.',['Dos zonas señaladas con cinta','Tarjeta de parar y seguir'],'Explica que es un cuento, sin sonidos fuertes ni dramatizaciones que asusten.',['Camina como un dinosaurio de cuento.','Al ver la tarjeta de parar, detente en tu espacio.','Al ver seguir, camina a la zona tranquila sin correr.','Cambia la señal por un gesto del grupo.'],12,{project:'Dinosaurios',related:['movimientos']});
  activity('museo','Abrimos nuestro museo','Proyecto','Comunicar descubrimientos a otras personas.',['Creaciones del proyecto','Carteles','Etiquetas','Mesas bajas'],'Elige con el grupo tres hallazgos o creaciones para exponer.',['Clasifica lo que vamos a mostrar.','Dicta una etiqueta y decide dónde colocarla.','Ensaya una frase de guía: aquí hemos descubierto…','Visita por turnos y celebra una aportación de cada persona.'],25,{project:'Dinosaurios',related:['carteles','etiquetas','diplomas']});
  activity('kusama-conocemos','Descubrimos a Yayoi Kusama','Proyecto','Observar rasgos que se repiten en la obra de una artista y expresar una preferencia.',['Dos o tres reproducciones elegidas por la maestra','Marcos de cartulina para mirar detalles','Círculos grandes de papel'],'Coloca una imagen con puntos, otra con una calabaza y otra instalación a la altura del grupo.',['Mira cada imagen durante unos segundos sin buscar una respuesta correcta.','Encuentra un punto, un color o una forma que se repita.','Elige el detalle que más te llama la atención y explica o señala por qué.','Coloca un círculo de papel junto a la imagen que te gustaría volver a observar.'],15,{project:'Yayoi Kusama',kusamaGroup:'lenguaje',type:'Actividad',easy:'Presenta solo dos imágenes y formula una pregunta concreta: ¿ves puntos o líneas?',extend:'Compara dos imágenes y busca algo que se repite y algo que cambia.',safety:'Usa reproducciones apropiadas para Infantil y evita imágenes con destellos o estímulos visuales intensos.'});
  activity('kusama-caza-puntos','La caza tranquila de los puntos','Lógica','Reconocer formas circulares en el entorno y agruparlas por una cualidad visible.',['Aros o marcos de cartulina','Cesta','Tarjetas de dos colores'],'Selecciona objetos grandes y seguros con partes circulares; no escondas piezas pequeñas.',['Busca desde tu sitio un círculo en el aula.','Acércate con la maestra y enmárcalo sin moverlo si forma parte del mobiliario.','Reúne en la cesta solo los objetos que puedan trasladarse con seguridad.','Agrupa los hallazgos por color o tamaño y explica el criterio con palabras o gestos.'],15,{project:'Yayoi Kusama',kusamaGroup:'puntos',easy:'Ofrece dos objetos y pregunta cuál tiene una parte redonda.',extend:'Busca un objeto que pueda pertenecer a dos grupos distintos.',safety:'No subirse a muebles ni recoger piezas pequeñas. La búsqueda se hace caminando y con supervisión.'});
  activity('kusama-punto-crece','Un punto que crece','Arte','Explorar círculos concéntricos mediante un gesto amplio y progresivo.',['Papel grande','Ceras gruesas','Témpera lavable opcional','Delantales'],'Marca un punto central grande en cada hoja y deja espacio para mover todo el brazo.',['Toca el punto central y recórrelo con el dedo.','Dibuja un círculo alrededor sin preocuparte por que quede perfecto.','Añade círculos cada vez mayores cambiando de color cuando quieras.','Observa cómo un punto pequeño ha ocupado gran parte del papel.'],20,{project:'Yayoi Kusama',kusamaGroup:'puntos',easy:'Usa una hoja con dos círculos anchos ya iniciados para recorrer y completar.',extend:'Alterna dos colores o dos grosores y descubre el patrón.',safety:'Usa materiales lavables y no tóxicos. Mantén la pintura fuera de ojos y boca.'});
  activity('kusama-sellos','Sellos de círculos','Motricidad fina','Regular la presión y crear una composición por repetición.',['Esponjas redondas grandes','Témpera lavable no tóxica','Bandejas poco profundas','Papel continuo','Paños'],'Prepara poca pintura y un sello grande por color; protege la mesa.',['Carga el sello con una capa fina de pintura.','Presiona y levanta para descubrir la huella circular.','Repite puntos juntos y separados, dejando también espacios vacíos.','Compara qué ocurre al apretar mucho o poco y limpia el material con ayuda.'],20,{project:'Yayoi Kusama',kusamaGroup:'puntos',easy:'Trabaja con un solo color y una zona de papel delimitada.',extend:'Crea una fila alternando dos colores o dos tamaños.',safety:'No uses tapones pequeños. Supervisa la pintura y limpia los derrames para evitar resbalones.'});
  activity('kusama-series','Series de lunares','Matemáticas','Reconocer y continuar patrones sencillos con círculos de colores.',['Círculos grandes de cartulina de dos colores','Tiras de papel','Velcro o masilla reutilizable colocada por un adulto'],'Prepara modelos AB y AAB con tres repeticiones completas y deja círculos sueltos.',['Lee el modelo señalando cada color.','Descubre el trocito que se repite.','Elige el círculo que continúa la serie y colócalo.','Crea una serie corta para que otra pareja la continúe.'],15,{project:'Yayoi Kusama',kusamaGroup:'puntos',related:['series-ab','series-aab'],easy:'Utiliza un patrón AB con solo dos opciones y copia antes de continuar.',extend:'Prueba un patrón AAB o inventa una unidad de tres círculos.',safety:'Círculos grandes, resistentes y bajo supervisión. El adulto maneja el adhesivo.'});
  activity('kusama-inicial','Mi inicial se llena de puntos','Lenguaje','Reconocer una letra significativa y seguir su recorrido con elementos circulares.',['Inicial del nombre en cartulina grande','Pegatinas circulares grandes o círculos de papel','Pegamento infantil','Nombre modelo'],'Prepara la inicial en mayúscula clara y coloca el nombre completo como referencia.',['Busca la primera letra de tu nombre en el modelo.','Recorre su forma con el dedo desde el punto de inicio.','Coloca círculos grandes a lo largo de la letra, sin exigir cubrirla por completo.','Encuentra otra inicial igual o distinta y explica qué has mirado.'],18,{project:'Yayoi Kusama',kusamaGroup:'lenguaje',related:['nombre','bandeja-nombre'],easy:'Ofrece la inicial con una franja ancha y pocos círculos ya colocados.',extend:'Alterna dos colores o busca la misma letra en otros nombres del grupo.',safety:'Usa pegatinas y piezas grandes. Supervisa para evitar que se lleven a la boca.'});
  activity('kusama-calabaza-observa','Miramos una calabaza','Asamblea','Observar una forma natural y describirla con vocabulario sencillo.',['Calabaza real o fotografía grande','Tela','Tarjetas de color y forma'],'Coloca la calabaza en una mesa estable y permite observar sin obligación de tocar.',['Mira su contorno y señala dónde empieza y termina.','Describe un color, una línea o una parte que se repite.','Rodea la calabaza con las manos sin levantarla.','Imagina qué puntos elegirías para decorarla en una creación propia.'],12,{project:'Yayoi Kusama',kusamaGroup:'formas',easy:'Ofrece dos palabras para elegir: redonda o alargada; lisa o con surcos.',extend:'Compara dos calabazas o dos fotografías por tamaño, color y forma.',safety:'El adulto mueve la calabaza. Comprueba alergias o sensibilidad antes de permitir el contacto.'});
  activity('kusama-calabaza-plastilina','Calabazas de plastilina y puntos','Motricidad fina','Combinar bola, presión, líneas y puntos en una pequeña escultura.',['Plastilina no tóxica','Bases individuales','Palitos anchos de modelado','Círculos de papel como inspiración'],'Reparte porciones grandes y muestra los gestos sin presentar un modelo obligatorio.',['Haz una bola con las dos manos.','Aplasta un poco y marca surcos suaves desde arriba hacia abajo.','Añade lunares con pequeñas presiones del dedo o con otro color de plastilina.','Gira la escultura y cuenta qué cambia al verla desde otro lado.'],20,{project:'Yayoi Kusama',kusamaGroup:'formas',easy:'Prepara una bola grande para que el niño solo presione y añada puntos.',extend:'Crea dos calabazas diferentes y ordénalas por tamaño.',safety:'Plastilina no tóxica, piezas grandes y supervisión constante. No usar palillos finos ni punzantes.'});
  activity('kusama-calabaza-grupo','La gran calabaza del grupo','Arte','Tomar decisiones compartidas en una obra colectiva de gran formato.',['Papel continuo','Silueta grande de calabaza dibujada por la maestra','Círculos de papel de varios tamaños','Pegamento infantil'],'Fija el papel a una mesa o pared baja y reparte los círculos en bandejas.',['Observa el espacio disponible y elige un círculo.','Decide dónde colocarlo sin tapar el trabajo de otra persona.','Añade puntos grandes y pequeños dejando zonas de descanso visual.','Mira la obra desde lejos y acuerda entre todos si está terminada.'],25,{project:'Yayoi Kusama',kusamaGroup:'formas',easy:'Ofrece dos colores y una zona concreta donde participar.',extend:'Antes de pegar, propone una regla compartida: alternar tamaños o crear caminos.',safety:'El adulto fija el papel y maneja cualquier adhesivo fuerte. No subir a sillas ni mesas.'});
  activity('kusama-contamos-puntos','¿Cuántos puntos necesita?','Matemáticas','Construir colecciones de uno a seis y comprobarlas uno a uno.',['Seis calabazas grandes de cartulina','Círculos grandes móviles','Tarjetas de cantidad 1-6','Bandejas'],'Coloca una tarjeta de cantidad junto a cada calabaza y distribuye los círculos.',['Elige una calabaza y mira su tarjeta.','Coloca un punto cada vez mientras cuentas tocándolo.','Comprueba de nuevo emparejando cada punto con un dedo o marca.','Cambia una tarjeta y decide si hay que añadir o retirar puntos.'],15,{project:'Yayoi Kusama',kusamaGroup:'puntos',related:['numeros-6','pinzas-6'],easy:'Trabaja solo con cantidades 1-3 y ofrece la colección modelo.',extend:'Compara dos calabazas y explica cuál tiene más, menos o la misma cantidad.',safety:'Todas las piezas deben ser grandes y resistentes; guárdalas al terminar.'});
  activity('kusama-clasifica-circulos','Círculos grandes, medianos y pequeños','Lógica','Clasificar por tamaño y cambiar de criterio de forma flexible.',['Círculos grandes de cartulina en tres tamaños y varios colores','Tres aros o bandejas','Tarjetas de criterio'],'Mezcla pocas piezas y presenta primero un único criterio.',['Compara dos círculos colocándolos uno sobre otro.','Agrupa por tamaño en tres bandejas.','Mezcla de nuevo y agrupa por color.','Elige un círculo que cambie de grupo cuando cambia la regla y explica por qué.'],15,{project:'Yayoi Kusama',kusamaGroup:'puntos',easy:'Utiliza solo grande y pequeño con cuatro piezas muy diferentes.',extend:'Busca una pieza con dos pistas: grande y roja, pequeña y azul.',safety:'Usa círculos grandes sin bordes cortantes y mantén los aros apoyados en el suelo o la mesa.'});
  activity('kusama-jardin','Jardín de flores y puntos','Arte','Crear formas vegetales de gran tamaño combinando color, simetría libre y repetición.',['Papel grande','Pétalos de papel ya recortados','Círculos de colores','Pegamento infantil','Ceras gruesas'],'Prepara pétalos grandes y varios centros circulares; no muestres una única solución.',['Elige un círculo para el centro de la flor.','Prueba distintas posiciones de los pétalos antes de pegar.','Añade puntos dentro, fuera o alrededor de la flor.','Reúne las flores del grupo para construir un jardín común.'],25,{project:'Yayoi Kusama',kusamaGroup:'formas',easy:'Ofrece un centro y cuatro pétalos grandes para ordenar.',extend:'Crea una flor con una regla de color o compara dos composiciones.',safety:'Las piezas las recorta previamente el adulto o se rasgan a mano. Usa pegamento infantil.'});
  activity('kusama-redes','Redes que continúan','Arte','Mantener un gesto gráfico repetido y observar cómo transforma una superficie.',['Papel grande','Ceras gruesas','Rotuladores lavables de punta ancha opcionales','Marcos de cartulina'],'Dibuja dos o tres bucles amplios como punto de partida y deja mucho espacio.',['Sigue un bucle con el dedo.','Añade otro al lado, arriba o abajo.','Continúa durante un tiempo breve y para cuando lo necesites.','Mira una zona con el marco y descubre caminos, huecos y repeticiones.'],15,{project:'Yayoi Kusama',kusamaGroup:'puntos',easy:'Completa una fila de tres bucles grandes ya iniciados.',extend:'Cambia de color al terminar cada fila o conecta dos redes.',safety:'Evita exigir repetición prolongada. Ofrece descanso visual y otra actividad si el patrón incomoda.'});
  activity('kusama-habitacion','Una habitación transformada','Proyecto','Participar en una instalación efímera y comprender que el arte también puede ocupar un espacio.',['Círculos grandes de papel reposicionable','Paneles de cartón','Muebles de juguete o rincón despejado','Cinta de baja adherencia para adulto'],'Delimita un rincón pequeño y cubre primero paneles móviles, no paredes ni objetos delicados.',['Entra y observa cómo es el espacio antes de cambiarlo.','Elige un círculo y decide en qué panel colocarlo.','Añade puntos por turnos hasta que el rincón parezca diferente.','Recorre la instalación, cuenta qué notas y retira juntos los círculos al finalizar.'],25,{project:'Yayoi Kusama',kusamaGroup:'espacios',easy:'Transforma solo una caja grande o un panel vertical.',extend:'Fotografía el antes y el después sin rostros y ordena las dos imágenes.',safety:'No pegar en suelo de paso, enchufes, cristales, piel ni ropa. El adulto comprueba adhesivos y accesos.'});
  activity('kusama-espejos','Puntos que se multiplican','Lógica','Explorar reflejos y repetición sin confundir imagen y objeto.',['Dos espejos infantiles irrompibles o láminas reflectantes','Círculos grandes de cartulina','Base antideslizante'],'El adulto fija los espejos sobre una mesa formando un ángulo amplio y comprueba que no se muevan.',['Coloca un círculo delante de un espejo y busca el círculo real y su reflejo.','Añade otro círculo y observa cuántos parecen verse.','Cambia la distancia y describe qué notas sin buscar una explicación cerrada.','Retira una pieza y comprueba qué imágenes desaparecen.'],12,{project:'Yayoi Kusama',kusamaGroup:'espacios',easy:'Utiliza un solo espejo fijo y una sola pieza.',extend:'Compara lo que ocurre con uno y con dos espejos.',safety:'Solo espejos infantiles irrompibles, bordes protegidos y fijados por un adulto. Nunca usar vidrio suelto.'});
  activity('kusama-camino','El camino de círculos','Psicomotricidad','Seguir una secuencia espacial y regular el movimiento mediante señales visuales.',['Círculos grandes antideslizantes de dos colores','Cinta de pintor','Tarjetas de parar y seguir'],'Crea un recorrido ancho a ras de suelo sin bloquear puertas ni zonas de paso.',['Avanza de círculo en círculo caminando despacio o señalándolos con la mano.','Para en un color acordado y continúa en el otro.','Cambia la regla: pasos grandes en círculos grandes y pequeños en los pequeños.','Inventa con el grupo una nueva forma segura de recorrer el camino.'],15,{project:'Yayoi Kusama',kusamaGroup:'espacios',easy:'Prepara una línea corta de cuatro círculos y permite hacerlo sentado con las manos.',extend:'Crea una serie AB de colores y anticipa el círculo siguiente.',safety:'Piezas completamente fijadas y antideslizantes. Sin saltos obligatorios, carreras ni ojos tapados.'});
  activity('kusama-punto-viajero','El cuento del punto viajero','Lenguaje','Construir una narración oral colectiva a partir de una forma sencilla.',['Círculo grande de cartulina','Tres fondos: aula, jardín y cielo','Caja o sobre'],'Guarda el círculo en la caja y coloca los tres fondos visibles.',['Descubre el punto y elige a qué lugar quiere viajar.','Decide qué encuentra allí usando una palabra, gesto o sonido.','Cada participante añade una acción breve y la maestra enlaza las ideas.','Elige un final y vuelve a contar el cuento con tres imágenes: inicio, viaje y llegada.'],18,{project:'Yayoi Kusama',kusamaGroup:'lenguaje',easy:'Ofrece dos fondos y preguntas de elección: ¿va al jardín o al cielo?',extend:'Añade un problema sencillo y busca dos finales posibles.',safety:'Respeta el derecho a escuchar o pasar turno. No es necesario memorizar ni escribir.'});
  activity('kusama-museo','Nuestro museo de Yayoi Kusama','Proyecto','Seleccionar, organizar y comunicar creaciones realizadas durante el curso.',['Creaciones del proyecto','Carteles de título','Mesas o paneles bajos','Círculos para señalizar el recorrido'],'Escoge con el grupo pocas obras de cada trimestre y deja recorridos amplios.',['Clasifica las creaciones por puntos, formas y espacios.','Dicta un título o una frase breve para una obra propia o colectiva.','Decide dónde colocar cada pieza y prueba el recorrido como visitante.','Invita a otra clase o a las familias y celebra una aportación de cada niño y niña.'],30,{project:'Yayoi Kusama',kusamaGroup:'lenguaje',related:['kusama-conocemos','kusama-calabaza-grupo','kusama-habitacion'],easy:'Expón tres obras y permite presentar señalando una de ellas.',extend:'Prepara en parejas una pregunta para los visitantes o una visita guiada de una frase.',safety:'Fija bien los trabajos, deja libres puertas y pasillos y no expongas nombres completos ni fotografías sin autorización.'});
  activity('bandeja-nombre','Mi inicial en una bandeja','Lenguaje','Explorar la forma de una letra significativa.',['Bandeja vacía','Cordón corto o plastilina','Nombre modelo'],'Escribe el nombre en mayúscula clara y destaca su inicial.',['Mira la letra inicial del nombre.','Recorre su forma con un dedo sobre el modelo.','Constrúyela con plastilina o cordón, sin buscar perfección.','Busca esa misma letra en otros nombres modelo.'],12,{related:['nombre','letras'],safety:'Preferir plastilina a arena o harina si hay sensibilidad al polvo. No usar cordones largos.'});
